import { chainClient, checkAbort, compareLogs } from './client.js';
import { cachedEvents } from './event-store.js';

/** Find the seat a new subscription consumes, or zero when updating an active one. */
export async function afkingSeatForStart(player, { client = chainClient(), timeoutMs = 15_000 } = {}) {
  const controller = new AbortController();
  let timer;
  const deadline = new Promise((_, reject) => {
    timer = setTimeout(() => {
      const error = new Error('AFKing seat lookup took too long. Please try again.');
      error.code = 'AFKING_SEAT_LOOKUP_TIMEOUT';
      controller.abort(error);
      reject(error);
    }, timeoutMs);
  });
  // Only read preparation has a deadline. A slow response after this rejects
  // cannot continue into a wallet request, and wallet approval never times out here.
  try { return await Promise.race([findSeat(client, player, controller.signal), deadline]); }
  finally { clearTimeout(timer); controller.abort(); }
}

async function findSeat(client, player, signal) {
  const address = player.toLowerCase();
  const snapshot = await client.snapshot({ fresh: true, signal });
  checkAbort(signal);
  const sub = await snapshot.call('GAME_LENS', 'subInfoFull', [client.address('GAME'), address]);
  checkAbort(signal);
  if (sub.active ?? sub[0]) {
    await snapshot.verify(signal);
    return 0n;
  }

  // Seats burn on activation. Scanning ownerOf(1..nextSerial) therefore queried
  // every historical seat, mostly reverts, before MetaMask could even open.
  // Indexed wallet transfers find just this player's inventory; the shared
  // event cache resumes paged history and verifies its block hashes on reuse.
  const [incoming, outgoing] = await Promise.all([
    cachedEvents(snapshot, 'AFKING_SUB_TOKEN', 'Transfer', { to: address }, { signal }),
    cachedEvents(snapshot, 'AFKING_SUB_TOKEN', 'Transfer', { from: address }, { signal }),
  ]);
  checkAbort(signal);
  const owned = new Set();
  for (const { args } of [...incoming, ...outgoing].sort(compareLogs)) {
    const id = BigInt(args.tokenId);
    if (args.to.toLowerCase() === address) owned.add(id);
    else owned.delete(id);
  }
  const seat = [...owned].sort((a, b) => a < b ? -1 : a > b ? 1 : 0)[0];
  if (seat == null) {
    await snapshot.verify(signal);
    throw new Error('Starting an AFKing subscription requires an unused seat.');
  }
  // Verify the selected seat against contract state at the same block. Never
  // interpret an RPC failure as a burned seat and silently keep scanning.
  const owner = await snapshot.call('AFKING_SUB_TOKEN', 'ownerOf', [seat]);
  checkAbort(signal);
  await snapshot.verify(signal);
  if (owner.toLowerCase() !== address) throw new Error('Your AFKing seat changed. Please try again.');
  return seat;
}
